DROP TABLE IF EXISTS sync_state CASCADE;
DROP TABLE IF EXISTS webhook_events CASCADE;
DROP TABLE IF EXISTS uptime_state CASCADE;
DROP TABLE IF EXISTS uptime_checks CASCADE;
